impl Character {
    pub fn __dinoco_load_player<'a, P, C, A>(
        item_keys: Vec<Option<dinoco::Uuid>>,
        include: &'a dinoco::IncludeNode,
        client: &'a dinoco::DinocoClient<A>,
        read_mode: dinoco::ReadMode,
        relation_field: impl Fn(&mut P) -> &mut Option<C> + Copy + Send + 'a,
    ) -> dinoco::IncludeLoaderFuture<'a, P>
    where
        A: dinoco::DinocoAdapter,
        C: dinoco::Projection<super::player::Player>,
    {
        Box::pin(async move {
            use std::collections::HashMap;

            struct DinocoChildRow<C> {
                item: Option<C>,
                relation_key: dinoco::Uuid,
            }

            impl<C> dinoco::DinocoRow for DinocoChildRow<C>
            where
                C: dinoco::Projection<super::player::Player>,
            {
                fn from_row<R: dinoco::DinocoGenericRow>(row: &R) -> dinoco::DinocoResult<Self> {
                    let relation_offset = C::columns().len();
                    let item = if row.get_optional::<dinoco::Uuid>(relation_offset)?.is_some() {
                        Some(C::from_row(row)?)
                    } else {
                        None
                    };

                    Ok(Self {
                        item,
                        relation_key: row.get(relation_offset + 1)?,
                    })
                }
            }

            let keys = item_keys.iter().flatten().cloned().collect::<Vec<_>>();

            if keys.is_empty() {
                return Ok(Box::new(|_: &mut [P]| {}) as dinoco::IncludeApplier<'a, P>);
            }

            let mut statement = dinoco::qualify_select_statement(
                include.statement.clone().unwrap_or_else(|| dinoco::SelectStatement::new().from("Player").select(C::columns())),
                "Player",
            );
            let mut select_columns = statement.select.clone();

            if select_columns.is_empty() {
                select_columns = C::columns()
                    .iter()
                    .map(|column| format!("{}.{}", "Player", column))
                    .collect::<Vec<_>>();
            }

            select_columns.push(format!("{}.{}", "Player", "id"));
            select_columns.push(format!("{}.{}", "Character", "playerId"));
            statement.select = select_columns;
            statement.conditions.push(
                dinoco::Expression::Column(format!("{}.{}", "Character", "playerId"))
                    .in_values(keys.iter().cloned().map(dinoco::IntoDinocoValue::into_dinoco_value).collect()),
            );
            statement.from = format!(
                "{} LEFT JOIN {} ON {}.{} = {}.{}",
                "Character",
                "Player",
                "Character",
                "playerId",
                "Player",
                "id",
            );

            let adapter = client.read_adapter(matches!(read_mode, dinoco::ReadMode::Primary));
            let partition_column = format!("{}.{}", "Character", "playerId");
            let (sql, params) = if statement.limit.is_some() || statement.skip.is_some() {
                dinoco::QueryBuilder::build_partitioned_select(adapter.dialect(), &statement, &partition_column, "__dinoco_row_num")
            } else {
                dinoco::QueryBuilder::build_select(adapter.dialect(), &statement)
            };
            let child_rows = adapter.query_as::<DinocoChildRow<C>>(&sql, &params).await?;
            let mut child_pairs = Vec::new();

            for row in child_rows {
                if let Some(item) = row.item {
                    child_pairs.push((row.relation_key, item));
                }
            }

            let relation_keys = child_pairs.iter().map(|(relation_key, _)| relation_key.clone()).collect::<Vec<_>>();
            let mut children = child_pairs.into_iter().map(|(_, item)| item).collect::<Vec<_>>();

            C::load_includes(&mut children, &include.includes, client, read_mode).await?;
            C::load_counts(&mut children, &include.counts, client, read_mode).await?;

            let mut grouped: HashMap<dinoco::Uuid, C> = HashMap::new();

            for (relation_key, child) in relation_keys.into_iter().zip(children.into_iter()) {
                grouped.insert(relation_key, child);
            }

            Ok(Box::new(move |items: &mut [P]| {
                for (item, key) in items.iter_mut().zip(item_keys.into_iter()) {
                    *relation_field(item) = key.and_then(|key| grouped.remove(&key));
                }
            }) as dinoco::IncludeApplier<'a, P>)
        })
    }
}

