impl Character {
    pub fn __dinoco_count_player<'a, P, A>(
        item_keys: Vec<Option<dinoco::Uuid>>,
        count: &'a dinoco::CountNode,
        client: &'a dinoco::DinocoClient<A>,
        _read_mode: dinoco::ReadMode,
        relation_field: impl Fn(&mut P) -> &mut usize + Copy + Send + 'a,
    ) -> dinoco::IncludeLoaderFuture<'a, P>
    where
        A: dinoco::DinocoAdapter,
    {
        Box::pin(async move {
            use std::collections::HashMap;

            #[derive(Debug, Clone, dinoco::Rowable)]
            struct DinocoRelationCountRow {
                id: dinoco::Uuid,
            }

            let keys = item_keys.iter().flatten().cloned().collect::<Vec<_>>();

            if keys.is_empty() {
                return Ok(Box::new(|_: &mut [P]| {}) as dinoco::IncludeApplier<'a, P>);
            }

            let adapter = client.read_adapter(false);
            let mut statement = count.statement.clone().unwrap_or_else(|| {
                dinoco::SelectStatement::new().from("Player").select(&["id"])
            });
            statement.select = vec!["id".to_string()];
            statement.conditions.push(dinoco::Expression::Column("id".to_string()).in_values(keys.iter().cloned().map(dinoco::IntoDinocoValue::into_dinoco_value).collect()));

            let rows = if statement.limit.is_some() || statement.skip.is_some() {
                let (sql, params) = dinoco::QueryBuilder::build_partitioned_select(
                    adapter.dialect(),
                    &statement,
                    "id",
                    "__dinoco_row_num",
                );
                adapter.query_as::<DinocoRelationCountRow>(&sql, &params).await?
            } else {
                let (sql, params) = dinoco::QueryBuilder::build_select(adapter.dialect(), &statement);
                adapter.query_as::<DinocoRelationCountRow>(&sql, &params).await?
            };

            let mut grouped: HashMap<dinoco::Uuid, usize> = HashMap::new();

            for row in rows {
                *grouped.entry(row.id).or_default() += 1;
            }

            Ok(Box::new(move |items: &mut [P]| {
                for (item, key) in items.iter_mut().zip(item_keys.into_iter()) {
                    *relation_field(item) = key.and_then(|key| grouped.remove(&key)).unwrap_or(0);
                }
            }) as dinoco::IncludeApplier<'a, P>)
        })
    }
}

#[derive(Debug, Clone, dinoco::serde::Serialize, dinoco::serde::Deserialize)]
#[serde(crate = "dinoco::serde")]
pub enum CharacterConnection {
    Player(dinoco::Uuid),
}

impl dinoco::InsertConnectionPayload<Character> for CharacterConnection {
    fn connection_updates(&self, parent: &Character) -> Vec<dinoco::ConnectionUpdatePlan> {
        match self {
            Self::Player(value) => vec![dinoco::ConnectionUpdatePlan {
                table_name: "Player",
                columns: &["id"],
                row: vec![parent.playerId.clone().into_dinoco_value()],
                conditions: vec![
                    dinoco::Expression::Column("id".to_string()).eq(value.clone().into_dinoco_value()),
                ],
            }],
        }
    }

    fn relation_links(&self, parent: &Character) -> Vec<dinoco::RelationLinkPlan> {
        match self {
            Self::Player(_) => Vec::new(),
        }
    }
}

